CREATE TABLE vehicle_expenses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, vehicle_id BIGINT UNSIGNED NOT NULL, financial_transaction_id BIGINT UNSIGNED NULL, expense_date DATE NOT NULL, expense_type ENUM('fuel','insurance','repair','registration','cleaning','other') NOT NULL, amount DECIMAL(15,2) NOT NULL, description VARCHAR(500) NULL, odometer_km DECIMAL(15,2) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_vehicle_expenses_ft (financial_transaction_id), KEY idx_ve_vehicle_date (vehicle_id,expense_date), CONSTRAINT chk_ve_values CHECK (amount > 0 AND (odometer_km IS NULL OR odometer_km >= 0)), CONSTRAINT fk_ve_vehicle FOREIGN KEY (vehicle_id) REFERENCES vehicles(id) ON DELETE RESTRICT, CONSTRAINT fk_ve_ft FOREIGN KEY (financial_transaction_id) REFERENCES financial_transactions(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
